insert into public.opportunities (id,title,org,descr,category,mode,cost,grade,eligibility,deadline,featured,published,url,tags,last_verified) values
($q$cern-beamline-for-schools$q$,$q$Beamline for Schools$q$,$q$CERN$q$,$q$Teams of high school students write a proposal for an experiment to run at a particle accelerator beamline. The best proposals win a trip to a partner lab to do the experiment. The page says travel, accommodation and equipment for winning teams are covered. Cycle note from the page: 2026 edition closed on 13 March 2026; the 2027 edition has not been announced yet.$q$,$q$Competitions$q$,$q$In person$q$,$q$Free$q$,$q$High school students (no age stated)$q$,$q$Described as a physics competition for high school students from all around the world. The page lists no country restriction. Participation is free of charge for eligible students, teachers and schools worldwide.$q$,null,false,true,$q$https://beamlineforschools.cern/$q$,array[$q$europe$q$,$q$research$q$,$q$science$q$,$q$switzerland$q$]::text[],$q$2026-10-14$q$::date),
($q$elements-of-ai$q$,$q$Elements of AI (Introduction to AI and Building AI)$q$,$q$University of Helsinki and MinnaLearn$q$,$q$Two free online courses about what AI is and how to build simple AI. You can finish them at your own pace. Introduction to AI needs no programming.$q$,$q$Courses$q$,$q$Online$q$,$q$Free$q$,$q$Not stated$q$,$q$Introduction to AI is for everyone interested in learning what AI is, with no complicated maths or programming needed. Building AI recommends basic Python skills. No age or country restriction is stated.$q$,null,false,true,$q$https://www.elementsofai.com/$q$,array[$q$coding$q$,$q$europe$q$,$q$finland$q$,$q$science$q$]::text[],$q$2026-10-14$q$::date),
($q$helsinki-open-moocs$q$,$q$University of Helsinki free online courses (MOOCs)$q$,$q$University of Helsinki$q$,$q$The university offers free online courses, such as Elements of AI, AI in Society and Ethics of AI. Taking a course is free. You only pay if you want the course recorded as university credits, and the page does not give that fee. Each course page shows its own open dates.$q$,$q$Courses$q$,$q$Online$q$,$q$Free$q$,$q$Not stated$q$,$q$The courses are open for everyone. You do not need a University of Helsinki account and no advance registration is needed. No eligibility requirements are mentioned.$q$,null,false,true,$q$https://www.helsinki.fi/en/admissions-and-education/open-university/open-online-courses-or-moocs$q$,array[$q$coding$q$,$q$europe$q$,$q$finland$q$,$q$science$q$]::text[],$q$2026-10-14$q$::date),
($q$oxford-sbs-high-school-summer-schools$q$,$q$Oxford Saïd Business School summer schools for high school students$q$,$q$Saïd Business School, University of Oxford$q$,$q$Two-week summer schools held in Oxford for 2027: AI and Machine Learning (18-31 July), Future Business Leaders (4-17 July or 18-31 July), Future Entrepreneurs and Future Global Strategists (1-14 August). Fees cover tuition, accommodation, meals and trips, but the amount is not on the page. Applications are reviewed on a rolling basis, so there is no fixed deadline.$q$,$q$Activities$q$,$q$In person$q$,$q$Paid$q$,$q$High school students aged 15-18 (one page says 15-18, another says 16-18)$q$,$q$Students from any country can apply. If English is not your first language you need at least B2 level English. Flights and visa costs are not included in the fee.$q$,null,false,true,$q$https://www.sbs.ox.ac.uk/programmes/youth-programmes$q$,array[$q$coding$q$,$q$entrepreneurship$q$,$q$europe$q$,$q$uk$q$,$q$united kingdom$q$]::text[],$q$2026-10-14$q$::date),
($q$imperial-global-summer-school$q$,$q$Imperial Global Summer School (pre-university programme)$q$,$q$Imperial College London$q$,$q$A two-week residential STEM summer school at Imperial. In week one you pick a subject such as Engineering, Physics, Chemistry, Data Science and AI, or Medicine and Life Sciences. Week two is a team Innovation Challenge. The 2026 fee was 7,695 pounds; the page shows 2026 information only. Cycle note from the page: 2026 applications closed; no 2027 deadline stated.$q$,$q$Activities$q$,$q$In person$q$,$q$Paid$q$,$q$Students aged 16 and 17$q$,$q$Must be 16 before the programme starts and not turn 18 before or during it. Needs strong academic results and strong English. The programme is described as being for international students. No nationality rule is stated.$q$,null,false,true,$q$https://www.imperial.ac.uk/lifelong-learning/for-individuals/global-summer-experiences/global-summer-school/$q$,array[$q$coding$q$,$q$europe$q$,$q$medicine$q$,$q$research$q$,$q$science$q$,$q$uk$q$,$q$united kingdom$q$]::text[],$q$2026-10-14$q$::date),
($q$cambridge-downing-16-18-summer-programme$q$,$q$Downing College Cambridge Summer Programme (ages 15-17)$q$,$q$Downing College, University of Cambridge$q$,$q$Two weeks of online study followed by two weeks in person at Downing College. The 2027 dates are 11-24 July (Programme B) and 25 July-7 August (Programme C). The fee is 9,000 pounds and the page gives no application closing date.$q$,$q$Activities$q$,$q$Hybrid$q$,$q$Paid$q$,$q$Students aged 15 to 17$q$,$q$For students aged 15 to 17. Applicants do a short interview about English and motivation. Flights, visa and travel insurance are not included. No country restriction is stated.$q$,null,false,true,$q$https://dow.cam.ac.uk/summer-programmes/16-18-summer-programme$q$,array[$q$europe$q$,$q$research$q$,$q$science$q$,$q$uk$q$,$q$united kingdom$q$]::text[],$q$2026-10-14$q$::date),
($q$oxplore-oxford$q$,$q$Oxplore: Big Questions$q$,$q$University of Oxford$q$,$q$A free Oxford website built around Big Questions, with articles, quizzes, podcasts, videos and image galleries. It also runs free online events that you can sign up for during the year. The page gives no dates.$q$,$q$Courses$q$,$q$Online$q$,$q$Free$q$,$q$Learners aged 11-18$q$,$q$For learners aged 11-18, and also teachers and families. The page mentions no country restriction and says it aims to reach learners everywhere. A free Oxplore account is used.$q$,null,false,true,$q$https://www.ox.ac.uk/admissions/undergraduate/supercurricular-hub/oxplore-home-of-big-questions$q$,array[$q$debate$q$,$q$europe$q$,$q$research$q$,$q$science$q$,$q$uk$q$,$q$united kingdom$q$]::text[],$q$2026-10-14$q$::date),
($q$nrich-cambridge-maths$q$,$q$NRICH free maths problems and resources$q$,$q$Faculties of Mathematics and Education, University of Cambridge$q$,$q$Thousands of free online maths resources for ages 3 to 18. They help students learn maths by investigating problems and discussing them.$q$,$q$Courses$q$,$q$Online$q$,$q$Free$q$,$q$Ages 3 to 18$q$,$q$Described as completely free and available to all. No restrictions are mentioned.$q$,null,false,true,$q$https://nrich.maths.org/2712$q$,array[$q$europe$q$,$q$math$q$,$q$uk$q$,$q$united kingdom$q$]::text[],$q$2026-10-14$q$::date),
($q$reach-oxford-scholarship$q$,$q$Reach Oxford Scholarship$q$,$q$University of Oxford$q$,$q$The award lasts 3 or 4 years depending on the course. It covers course fees, a living-costs grant and one return air fare per year. About 2-3 awards are given each year, and you must apply for admission to Oxford first.$q$,$q$Scholarships$q$,$q$In person$q$,$q$Funded$q$,$q$Undergraduate (new students, all subjects except medicine)$q$,$q$Egypt is on the list of eligible countries. You must be a citizen of a country that gets official development assistance (OECD DAC). You need an offer from Oxford, high academic ability, financial need and social commitment, and you must be unable to study for a degree in your own country. You should plan to return home after your studies. Priority goes to students who have not studied at undergraduate level before.$q$,$q$Jan 26, 2027 (2027 entry)$q$,false,true,$q$https://www.ox.ac.uk/admissions/undergraduate/fees-and-funding/oxford-support/reach-oxford-scholarship$q$,array[$q$europe$q$,$q$research$q$,$q$science$q$,$q$uk$q$,$q$arab$q$]::text[],$q$2026-10-14$q$::date),
($q$ucl-global-undergraduate-scholarship$q$,$q$UCL Global Undergraduate Scholarship$q$,$q$University College London (UCL)$q$,$q$10 awards cover full tuition fees, a maintenance allowance and a fixed allowance for extra costs such as visa fees. 20 awards cover full tuition fees only. Awards cover the standard length of the degree. Cycle note from the page: 5pm BST, Monday 27 April 2026 (2026/27 entry cycle; check the page for the next cycle).$q$,$q$Scholarships$q$,$q$In person$q$,$q$Funded$q$,$q$Full-time undergraduate degree (2026/27 entry)$q$,$q$Candidates can be from any country outside the UK. You must be eligible to pay the overseas tuition fee rate, come from a low income background, and have applied for a full-time undergraduate degree at UCL for 2026/27. UCL generally treats household income of 42,875 pounds or less as low income, but it also looks at applications above that.$q$,null,false,true,$q$https://www.ucl.ac.uk/scholarships/ucl-global-undergraduate-scholarship$q$,array[$q$europe$q$,$q$research$q$,$q$science$q$,$q$uk$q$]::text[],$q$2026-10-14$q$::date),
($q$eth-zurich-excellence-scholarship$q$,$q$ETH Zurich Excellence Scholarship and Opportunity Programme (ESOP)$q$,$q$ETH Zurich$q$,$q$The scholarship is CHF 12,000 per semester, and CHF 13,500 from HS27. It covers living and study costs and includes a tuition fee waiver, for the normal length of the programme (three or four semesters). About 60 scholarships are planned for 2027/28, and a February interview may be part of selection.$q$,$q$Scholarships$q$,$q$In person$q$,$q$Funded$q$,$q$Master's (not MAS)$q$,$q$For excellent Master's students. The main rule is a strong Bachelor's result (top 10% of your Bachelor's programme, grade A). You cannot apply if you already study in an ETH Master's programme or already hold a Master's degree. You upload a pre-proposal for your Master's thesis and may need two professors for reference letters. No nationality restriction is stated.$q$,$q$November 1 to 30, for a start in autumn 2027$q$,false,true,$q$https://ethz.ch/students/en/studies/financial/scholarships/excellencescholarship.html$q$,array[$q$coding$q$,$q$europe$q$,$q$math$q$,$q$research$q$,$q$science$q$,$q$switzerland$q$]::text[],$q$2026-10-14$q$::date),
($q$nl-scholarship-holland$q$,$q$NL Scholarship (formerly Holland Scholarship)$q$,$q$Study in NL (Dutch higher education)$q$,$q$The scholarship is 5,000 euros, paid in the first year of study. The page says it is not a full-tuition scholarship. Applications for 2026-2027 opened on 1 November 2025. Deadlines are set by each institution, so check the website of the university you want.$q$,$q$Scholarships$q$,$q$In person$q$,$q$Funded$q$,$q$Full-time bachelor's or master's at a participating Dutch institution$q$,$q$Open only to non-EEA citizens. You must enter a full-time bachelor's or master's programme at a participating Dutch higher education institution and meet that institution's entry requirements. You must not already have a degree from a Dutch institution.$q$,null,false,true,$q$https://www.studyinnl.org/finances/holland-scholarship$q$,array[$q$europe$q$,$q$netherlands$q$,$q$research$q$]::text[],$q$2026-10-14$q$::date),
($q$erasmus-mundus-joint-masters$q$,$q$Erasmus Mundus Joint Masters$q$,$q$European Commission (Erasmus+)$q$,$q$Scholarships cover participation costs and help with travel, visa costs and a living allowance. Full scholarships may go to the best-ranked students worldwide. Each master's website lists its own entry requirements and deadline. Cycle note from the page: Not stated as one date. Most programmes: between October and January for courses starting the next academic year.$q$,$q$Scholarships$q$,$q$In person$q$,$q$Funded$q$,$q$Master's$q$,$q$The page says students from all over the world are welcome. You need a bachelor's degree, or be in your last year of bachelor studies and graduate before the master's starts. Equivalent qualifications can count if officially recognised in the country that awarded them. You apply directly to the programme you choose.$q$,null,false,true,$q$https://erasmus-plus.ec.europa.eu/opportunities/opportunities-for-individuals/students/erasmus-mundus-joint-masters$q$,array[$q$europe$q$,$q$languages$q$,$q$research$q$,$q$science$q$]::text[],$q$2026-10-14$q$::date),
($q$eiffel-excellence-scholarship$q$,$q$Eiffel Excellence Scholarship Programme$q$,$q$Campus France (French government)$q$,$q$Campus France must receive applications by 8 January 2026, and results come from 30 March 2026. The page does not list amounts or what is covered. Cycle note from the page: 8 January 2026 (2026 session; check the page for the next session).$q$,$q$Scholarships$q$,$q$In person$q$,$q$Funded$q$,$q$Master's and PhD$q$,$q$For foreign students: it encourages applicants up to 29 years old at master's level and up to 35 at PhD level. The page does not name which countries qualify. Only French higher education institutions can submit applications, so you apply through the institution you want to join.$q$,null,false,true,$q$https://www.campusfrance.org/en/eiffel-scholarship-program-of-excellence$q$,array[$q$europe$q$,$q$france$q$,$q$research$q$]::text[],$q$2026-10-14$q$::date),
($q$aalto-excellence-scholarship$q$,$q$Aalto University Excellence Scholarship$q$,$q$Aalto University (Finland)$q$,$q$It is a full tuition fee waiver for the target time of the degree. It does not cover living costs. Bachelor's graduates who held it may get a master's waiver if they finish in 3 years with a weighted average of at least 3.50.$q$,$q$Scholarships$q$,$q$In person$q$,$q$Not stated$q$,$q$Bachelor's (3 years) and master's (2 years); page covers study rights starting on or after 1 August 2025$q$,$q$Merit-based. You apply during the admission process. The page says there is a very limited number of scholarships. Students must study full-time under their study plan and are reviewed each year.$q$,null,false,true,$q$https://www.aalto.fi/en/international-students/scholarships-study-right-started-on-or-after-1-august-2025$q$,array[$q$coding$q$,$q$europe$q$,$q$finland$q$,$q$science$q$]::text[],$q$2026-10-14$q$::date),
($q$polimi-merit-scholarships$q$,$q$Politecnico di Milano Merit-Based Scholarships$q$,$q$Politecnico di Milano (Italy)$q$,$q$Every award gives a full tuition waiver; you pay only an administrative fee of about 170 euros. Some awards add an allowance of up to 10,000 euros per year (gross). Admitted bachelor's students can also apply for DSU grants, but the page gives no amounts for those. Cycle note from the page: English certificate due 21 February 2026 (2025-26 call); for 2026-27 an extra no-fee application form is needed.$q$,$q$Scholarships$q$,$q$In person$q$,$q$Funded$q$,$q$Master of Science (page also lists regional DSU grants for bachelor's students)$q$,$q$Top international candidates admitted to an English-taught Master of Science who applied in the Early Bird period and paid the fee between 1 October and 1 December 2025. GPA and academic achievements count most. The same page lists an 'Invest your Talent in Italy' scholarship for September-intake applicants from several countries including Egypt.$q$,null,false,true,$q$https://www.polimi.it/en/prospective-students/scholarships$q$,array[$q$art$q$,$q$coding$q$,$q$europe$q$,$q$italy$q$,$q$science$q$]::text[],$q$2026-10-14$q$::date),
($q$pearson-international-scholarship-utoronto$q$,$q$Lester B. Pearson International Scholarship$q$,$q$University of Toronto$q$,$q$The scholarship covers tuition, books, incidental fees and full residence support for four years at U of T. About 37 students are named Pearson Scholars each year. Your school must nominate you, so ask your school counsellor now.$q$,$q$Scholarships$q$,$q$In person$q$,$q$Funded$q$,$q$Final year of senior secondary school in 2026/2027, or graduated no earlier than June 2026; study must start at U of T in September 2027$q$,$q$For international students (non-Canadians who need a study permit). The student must be nominated by their own school, and a school can nominate only one student per year. The student must also apply to at least one U of T undergraduate program. The page does not list eligible countries.$q$,$q$November 6, 2026 (scholarship application and documents, 2027 entry). The school nomination step for schools new to the program closed October 9, 2026.$q$,false,true,$q$https://future.utoronto.ca/pearson-scholarships$q$,array[$q$canada$q$]::text[],$q$2026-10-17$q$::date),
($q$usaco-contests$q$,$q$USACO (USA Computing Olympiad) online contests$q$,$q$USACO$q$,$q$USACO runs online programming contests (four per year) for students at all levels. New participants start in the bronze division and move up when they score well. The 2026-27 contest dates are not on the page; the 2025-26 season has ended.$q$,$q$Competitions$q$,$q$Online$q$,$q$Free$q$,$q$High-school computing students at all levels$q$,$q$The page says all are welcome to take part in the online USACO contests and training. Only pre-college students in the USA can be picked as finalists for the training camp and the USA IOI or EGOI teams. There is never any fee for participation.$q$,null,false,true,$q$https://usaco.org/index.php?page=instructions$q$,array[$q$coding$q$,$q$math$q$,$q$usa$q$]::text[],$q$2026-10-17$q$::date),
($q$maa-amc-international$q$,$q$MAA American Mathematics Competitions (AMC) through international group leaders$q$,$q$Mathematical Association of America$q$,$q$The MAA page lists an International Group Leader whose region includes Egypt. Students register through that leader, not directly. Contact AMCinternational@maa.org for details; grade levels, fees and dates are not on the page.$q$,$q$Competitions$q$,$q$Not stated$q$,$q$Not stated$q$,$q$Not stated$q$,$q$For 2026-27 the AMC competitions are offered only to schools with USA, Canada or APO/FPO/DPO addresses, except schools registered with an AMC international partner. Students outside these places must register through the International Group Leader (IGL) for the country they live in. The IGL list includes Egypt.$q$,null,false,true,$q$https://maa.org/amc-international/$q$,array[$q$math$q$,$q$usa$q$]::text[],$q$2026-10-17$q$::date),
($q$yygs-yale$q$,$q$Yale Young Global Scholars (YYGS)$q$,$q$Yale University$q$,$q$YYGS is a two-week residential program at Yale's campus. Admission and aid decisions for Regular Decision come by March 10, 2027. The tuition amount and 2027 session dates are not stated on the official pages we read.$q$,$q$Activities$q$,$q$In person$q$,$q$Paid$q$,$q$US Grade 10 or 11 or the international equivalent; at least 16 years old (as stated on the FAQ page)$q$,$q$The FAQ page says YYGS accepts applicants from all countries. Need-based aid is given as a tuition discount of up to 100% and is open equally to domestic and international students. Aid must be requested inside the application. The application fee is $100 for Regular Decision, and a fee waiver can be requested.$q$,$q$January 6, 2027 (Regular Decision, 11:59pm ET); Early Action closed October 15, 2026$q$,false,true,$q$https://globalscholars.yale.edu/application-deadlines$q$,array[$q$debate$q$,$q$research$q$,$q$usa$q$]::text[],$q$2026-10-17$q$::date),
($q$stanford-pre-collegiate-summer-institutes$q$,$q$Stanford Pre-Collegiate Summer Institutes$q$,$q$Stanford University$q$,$q$Summer 2026 tuition was $3,200, and need-based financial aid was available. The Summer 2026 application closed March 13, 2026. The page does not state whether the program is online or in person, and the Summer 2027 dates are not posted yet.$q$,$q$Activities$q$,$q$Not stated$q$,$q$Paid$q$,$q$Grades 8-11; older than 13 and younger than 19 during the program$q$,$q$International applicants can apply and aid can be given to domestic and international participants. Students must be fluent in English, but TOEFL and IELTS scores are not required. Standardized test scores are optional.$q$,null,false,true,$q$https://summerinstitutes.spcs.stanford.edu/admissions$q$,array[$q$math$q$,$q$research$q$,$q$science$q$,$q$usa$q$]::text[],$q$2026-10-17$q$::date),
($q$wolfram-high-school-summer-research-program$q$,$q$Wolfram High School Summer Research Program$q$,$q$Wolfram Research$q$,$q$The page lists the 2026 program at Bentley University in Boston, June 24 to July 11, 2026. Applications open at the beginning of November, with dates such as January 18 and March 22, but the page does not give the year. The tuition amount is not stated.$q$,$q$Research$q$,$q$In person$q$,$q$Paid$q$,$q$Students under 18 at the end of the program; any STEM background$q$,$q$The page says it accepts international students and applicants should be motivated, independent learners with a STEM background. Need-based scholarships are available and admission is need-blind. The grade level is not stated.$q$,null,false,true,$q$https://education.wolfram.com/summer-camp/admission$q$,array[$q$coding$q$,$q$research$q$,$q$science$q$,$q$usa$q$]::text[],$q$2026-10-17$q$::date),
($q$harvard-online-free-courses$q$,$q$Harvard Online free courses$q$,$q$Harvard Professional and Lifelong Learning$q$,$q$The free catalog includes online courses such as CS50's Introduction to Cybersecurity (5 weeks), Data Science: Probability (8 weeks) and Backyard Meteorology (6 weeks). Courses have different lengths and subjects.$q$,$q$Courses$q$,$q$Online$q$,$q$Free$q$,$q$Not stated$q$,$q$Not stated. The catalog page marks courses as Free* but does not explain the asterisk or list age or country rules. Check each course page and the Terms of Use.$q$,null,false,true,$q$https://pll.harvard.edu/catalog/free$q$,array[$q$coding$q$,$q$math$q$,$q$science$q$,$q$usa$q$]::text[],$q$2026-10-17$q$::date),
($q$mit-international-financial-aid$q$,$q$MIT financial aid for international undergraduates$q$,$q$Massachusetts Institute of Technology$q$,$q$MIT's aid deadlines are Early Action November 30 and Regular Action February 15, the same for domestic and international students, but the page does not state the year. If you apply in a later cycle, check the page for the exact dates.$q$,$q$Universities$q$,$q$In person$q$,$q$Funded$q$,$q$First-year undergraduate applicants$q$,$q$International students are those not eligible for US federal aid. They are considered for aid with the same process as all applicants. To be considered you submit the CSS Profile (MIT code 3514) and parent tax or income documents through IDOC. MIT says it is committed to meeting 100% of demonstrated financial need for international students.$q$,null,false,true,$q$https://sfs.mit.edu/undergraduate-students/apply-for-aid/international$q$,array[$q$coding$q$,$q$research$q$,$q$science$q$,$q$usa$q$]::text[],$q$2026-10-17$q$::date),
($q$princeton-international-financial-aid$q$,$q$Princeton need-based aid for international students$q$,$q$Princeton University$q$,$q$The cost and aid page lists aid forms due Early Action Nov. 9 and Regular Decision Feb. 1, but gives no year. For 2026-27 it lists tuition of $68,140 and an average grant of $83,000 for aid students.$q$,$q$Universities$q$,$q$In person$q$,$q$Funded$q$,$q$Undergraduate applicants$q$,$q$The page says Princeton admission is need-blind and the full need of admitted international students is met the same way as for US students. Aid is a grant, not a loan, and is based on need only. There are no merit scholarships.$q$,null,false,true,$q$https://admission.princeton.edu/apply/international-students$q$,array[$q$research$q$,$q$usa$q$]::text[],$q$2026-10-17$q$::date),
($q$harvard-college-international-aid$q$,$q$Harvard College financial aid for international applicants$q$,$q$Harvard College$q$,$q$Applicants apply through the Common Application with the required supplements. This page gives no aid deadlines or forms; those are on Harvard's Apply for Financial Aid pages.$q$,$q$Universities$q$,$q$In person$q$,$q$Funded$q$,$q$First-year applicants$q$,$q$The page says financial aid policies are the same for all applicants regardless of nationality or citizenship. Admission decisions are made without regard to whether a student applied for aid, and Harvard meets each student's demonstrated need. Aid awards include a travel allowance.$q$,null,false,true,$q$https://college.harvard.edu/admissions/apply/international-applicants$q$,array[$q$research$q$,$q$usa$q$]::text[],$q$2026-10-17$q$::date),
($q$waterloo-presidents-scholarship-of-distinction$q$,$q$University of Waterloo President's Scholarship of Distinction$q$,$q$University of Waterloo$q$,$q$The award is a one-time $2,000 scholarship. After first year, recipients can get a $1,500 Research Award and a $1,500 International Experience Award. The page does not state an application deadline.$q$,$q$Scholarships$q$,$q$In person$q$,$q$Funded$q$,$q$First-year, full-time degree students starting post-secondary study for the first time$q$,$q$Open to Canadian or permanent resident students and international students. You need an early-May admission average of 95% or higher in the program you accepted. The award does not apply at Renison University College or St. Jerome's University.$q$,null,false,true,$q$https://uwaterloo.ca/undergraduate-entrance-awards/awards/university-waterloo-presidents-scholarship-distinction$q$,array[$q$canada$q$,$q$research$q$]::text[],$q$2026-10-17$q$::date),
($q$ualberta-international-entrance-scholarships$q$,$q$University of Alberta international entrance scholarships$q$,$q$University of Alberta$q$,$q$The President's International Distinction Scholarship is up to CAN $120,000 over four years and goes to 25 students each year. The deadline for application-based scholarships is January 10, but the page does not state the year.$q$,$q$Scholarships$q$,$q$In person$q$,$q$Funded$q$,$q$First-year undergraduate applicants$q$,$q$Some awards need no separate application, such as the International Admission Scholarship (up to CAN $10,000, based on admission average). Others need one scholarship application, such as the President's International Distinction Scholarship and the International Leader Scholarship (up to CAN $15,000). You must apply to an undergraduate program first. The student-visa wording on the page applies to the larger awards.$q$,null,false,true,$q$https://www.ualberta.ca/en/admissions/tuition-and-scholarships/international-entrance-scholarships/index.html$q$,array[$q$canada$q$]::text[],$q$2026-10-17$q$::date),
($q$turkiye-burslari-bachelor$q$,$q$Turkiye Scholarships (Turkiye Burslari) for Bachelor's Degrees$q$,$q$Presidency for Turks Abroad and Related Communities (Turkiye Burslari)$q$,$q$This is the Turkish government scholarship for bachelor's study. It covers university placement, tuition, accommodation, health insurance, a monthly stipend (6,500 TL for undergraduates), a one-year Turkish course and a flight ticket. The calendar page says the general application window is 10 January to 20 February each year, but it does not name a year, so check the next window.$q$,$q$Scholarships$q$,$q$In person$q$,$q$Funded$q$,$q$Not stated$q$,$q$The page states no general nationality restriction and no age limit. Merit scholarship table asks for a GWA of 90%, an SAT of 1350 (1400 for engineering) or IB 33+, TOEFL iBT 80 or IELTS 6.5, and one extra condition such as a top-10 national exam rank or an international science olympiad medal. Some scholarships may favor students from certain countries.$q$,null,false,true,$q$https://www.turkiyeburslari.gov.tr/fulltimeprograms$q$,array[$q$turkey$q$]::text[],$q$2026-10-17$q$::date),
($q$koc-university-merit-scholarship-international$q$,$q$Koc University Merit Scholarship for International Undergraduates$q$,$q$Koc University$q$,$q$Koc University looks at every new international undergraduate for a full (100%) or partial (25%, 50% or 75%) tuition scholarship. There is no separate form or application period; you learn the result in your offer letter. The scholarship covers tuition only and lasts for the 4 years of the program.$q$,$q$Universities$q$,$q$In person$q$,$q$Funded$q$,$q$New undergraduate international candidates$q$,$q$The page says all new undergraduate international candidates are evaluated automatically for merit scholarships. The School of Medicine does not award merit or need-based scholarships.$q$,null,false,true,$q$https://international.ku.edu.tr/undergraduate-programs/tuition-and-scholarships$q$,array[$q$turkey$q$]::text[],$q$2026-10-17$q$::date),
($q$bilkent-university-international-undergraduate-aid$q$,$q$Bilkent University Financial Assistance for International Undergraduates$q$,$q$Bilkent University$q$,$q$Bilkent's scholarship page has a short note for international students. Financial help is decided from high school grades and exam scores. Coverage and dates are not on this page, which sends international students to a separate page.$q$,$q$Universities$q$,$q$In person$q$,$q$Not stated$q$,$q$Not stated$q$,$q$The page says international applicants who ask for financial assistance are judged by their high school grades and their national and international exam scores. The Full, 50% and Comprehensive scholarships listed on the page are for Turkish citizens.$q$,null,false,true,$q$https://w3.bilkent.edu.tr/bilkent/scholarships/$q$,array[$q$turkey$q$]::text[],$q$2026-10-17$q$::date),
($q$kfupm-international-undergraduate-scholarship$q$,$q$KFUPM Full Scholarship for International Undergraduates$q$,$q$King Fahd University of Petroleum and Minerals (KFUPM)$q$,$q$International students living outside Saudi Arabia get a full scholarship to study at KFUPM. It lists on-campus housing, free loaned textbooks, a monthly allowance and care at the campus clinic. The page gives no deadline or intake dates; it points to admissions@kfupm.edu.sa.$q$,$q$Scholarships$q$,$q$In person$q$,$q$Funded$q$,$q$Not stated$q$,$q$The page says: As an international student living outside Saudi Arabia, your tuition fees are waived. No other eligibility rules are given.$q$,null,false,true,$q$https://kfupm.edu.sa/study/international-students/fees-and-scholarships$q$,array[$q$saudi$q$]::text[],$q$2026-10-17$q$::date),
($q$khalifa-university-international-undergraduate-scholarships$q$,$q$Khalifa University Scholarships for International Undergraduates$q$,$q$Khalifa University$q$,$q$Khalifa University has three scholarship tiers. Tier I is a 100% tuition waiver plus textbooks, Tier II is a 50% or 75% tuition waiver plus textbooks, and Tier III gives textbooks and a chance at a tuition discount for a CGPA of 3.8. Tier I students must work for or study further at the university after graduating if it offers this. The page lists no deadline (page is the 2024-2025 catalog).$q$,$q$Scholarships$q$,$q$In person$q$,$q$Funded$q$,$q$Full-time undergraduate students$q$,$q$The catalog says the scholarships are for qualified international students enrolled in undergraduate programs full-time. Awards depend on the offer received at admission and on keeping a set CGPA each semester.$q$,null,false,true,$q$https://ku-ae.smartcatalogiq.com/en/2024-2025/undergraduate-catalog/undergraduate-admissions/scholarships/scholarships-for-international-students$q$,array[$q$uae$q$]::text[],$q$2026-10-17$q$::date),
($q$aus-president-scholarship$q$,$q$AUS President Scholarship$q$,$q$American University of Sharjah (AUS)$q$,$q$This scholarship covers 100% of tuition and lab fees, a monthly stipend, on-campus housing, three round-trip tickets, student medical insurance and an application fee waiver. Up to 20 applicants get it each year and it can be renewed. The page shows a deadline of 17 April 2025, which is past, so ask scholarship@aus.edu for the next date.$q$,$q$Scholarships$q$,$q$In person$q$,$q$Funded$q$,$q$Final-year secondary school students who plan to start at AUS in the fall$q$,$q$Open to applicants who completed secondary education outside the UAE. The page sets no nationality restriction. Selection is mostly based on academic excellence and other achievements.$q$,null,false,true,$q$https://info.aus.edu/president-scholarship$q$,array[$q$uae$q$]::text[],$q$2026-10-17$q$::date),
($q$zayed-university-international-merit-scholarship$q$,$q$Zayed University Merit Scholarships for International Undergraduates$q$,$q$Zayed University$q$,$q$Zayed University gives a limited number of merit scholarships at the start of each Fall and Spring semester. The President's Award covers 100% of tuition and the Academic Merit Scholarship covers 25% or 50%. The page does not give a date.$q$,$q$Scholarships$q$,$q$In person$q$,$q$Funded$q$,$q$Self-funding international undergraduate students$q$,$q$The page says scholarships are offered to eligible, self-funding international students in undergraduate programs. Awards depend on high school grades, a math test score, extracurricular activities, a reference letter and submitting before the deadline. Meeting the rules does not guarantee an award.$q$,null,false,true,$q$https://zu.ac.ae/main/en/undergraduate-programs/_images/tuition-scholarship$q$,array[$q$uae$q$]::text[],$q$2026-10-17$q$::date),
($q$qatar-university-international-students-scholarship$q$,$q$Qatar University International Students Scholarship (Undergraduate)$q$,$q$Qatar University$q$,$q$The scholarship covers tuition and textbook fees, a monthly payment of 500 QR, student housing with transport, a yearly round-trip air ticket and a residence permit. The QU talent scholarship is also open to international undergraduates. The dates on the timeline page are for Qatar residents, so no deadline for international applicants is stated.$q$,$q$Scholarships$q$,$q$In person$q$,$q$Funded$q$,$q$International students applying to undergraduate programs$q$,$q$For international students who apply to undergraduate programs. You need a high school certificate or equivalent with at least a 95% average and final admission. Transfer, visiting and non-degree students are not eligible. Selection is competitive.$q$,null,false,true,$q$https://www.qu.edu.qa/en-us/students/admission/scholarships/Pages/types.aspx$q$,array[$q$qatar$q$]::text[],$q$2026-10-17$q$::date),
($q$nus-international-undergraduate-scholarship$q$,$q$NUS International Undergraduate Scholarship$q$,$q$National University of Singapore (NUS)$q$,$q$All eligible students who apply for NUS undergraduate admission are considered, so there is no separate scholarship form. It covers 100% of subsidised tuition, a S$5,800 yearly living allowance, S$5,000 yearly for accommodation and a S$1,750 computer allowance. Interviews run January to July and the page gives no application deadline.$q$,$q$Scholarships$q$,$q$In person$q$,$q$Funded$q$,$q$Applicants to a full-time undergraduate degree at NUS$q$,$q$Open to citizens of all countries except Singapore. Needs strong leadership, an outstanding co-curricular record and outstanding high school results. Transfer applicants are not eligible. Recipients who take the MOE Tuition Grant must work for a Singapore company for 3 years after graduating.$q$,null,false,true,$q$https://nus.edu.sg/oam/scholarships/scholarships-for-freshmen-international-students/nus-international-undergraduate-scholarship$q$,array[$q$singapore$q$]::text[],$q$2026-10-17$q$::date),
($q$chinese-government-scholarship-undergraduate-2026$q$,$q$Chinese Government Scholarship for Undergraduates (2026/2027 cycle)$q$,$q$Chinese Government (Chinese Consulate notice)$q$,$q$This is a full scholarship that does not cover international travel. The 2026/2027 cycle closed on 8 February 2026, and the CSCA test dates were 21 December 2025 and 25 January 2026. Watch for the next cycle notice from a Chinese embassy or consulate.$q$,$q$Scholarships$q$,$q$In person$q$,$q$Funded$q$,$q$Not stated$q$,$q$Undergraduate applicants must register for and take the China Scholastic Competency Assessment (CSCA) before applying and upload a valid CSCA score report. The page states no age requirement.$q$,null,false,true,$q$https://melbourne.china-consulate.gov.cn/eng/tz/202511/t20251113_11752245.htm$q$,array[$q$china$q$]::text[],$q$2026-10-17$q$::date),
($q$kaist-international-undergraduate-admissions-2027$q$,$q$KAIST International Undergraduate Admissions (2027)$q$,$q$KAIST Office of Admissions$q$,$q$KAIST has two application tracks for international undergraduates. Early track: apply 22 September to 22 October 2026, results 7 January 2027. Regular track (fall only): apply 10 November 2026 to 14 January 2027, results 25 March 2027. A recommendation letter is due a week after each deadline, and an interview is not required for everyone.$q$,$q$Universities$q$,$q$In person$q$,$q$Not stated$q$,$q$Not stated$q$,$q$The page does not list eligibility rules or scholarships. It gives the schedule for international undergraduate applicants.$q$,$q$Early: 22 October 2026, 6:00 PM KST. Regular: 14 January 2027, 6:00 PM KST (2027 admissions)$q$,false,true,$q$https://admission.kaist.ac.kr/intl-undergraduate/application$q$,array[$q$korea$q$]::text[],$q$2026-10-17$q$::date),
($q$postech-international-undergraduate-scholarships$q$,$q$POSTECH Scholarships for International Undergraduates$q$,$q$POSTECH$q$,$q$Admitted international students get a full tuition waiver in the first semester and can keep it for up to 8 semesters. Extra support listed includes airfare up to KRW 2,500,000, a living allowance of KRW 500,000 a month and KRW 300,000 for a TOPIK level 4 result. The page gives no application dates.$q$,$q$Scholarships$q$,$q$In person$q$,$q$Funded$q$,$q$International students admitted through the international undergraduate admission track$q$,$q$Students with foreign nationality admitted through the domestic or Korean overseas tracks do not qualify. Keeping the tuition waiver needs a GPA of at least 3.0 out of 4.3 in the previous semester.$q$,null,false,true,$q$https://adm-iu.postech.ac.kr/user/comm/menu/e2afb97fa1b8f43c574be0dabef78f87/content/index.do$q$,array[$q$korea$q$]::text[],$q$2026-10-17$q$::date),
($q$apu-tuition-reduction-scholarship-2027$q$,$q$APU Tuition Reduction Scholarship (2027 enrollment)$q$,$q$Ritsumeikan Asia Pacific University (APU)$q$,$q$APU reduces tuition by 30%, 50%, 65%, 80% or 100% until graduation, with a yearly review and renewal up to the eighth semester. For first-year students, 100% is 1,455,000 JPY a year. Selection uses your documents, a recorded interview and family finances; the page gives no dates and points to the APU application schedule page.$q$,$q$Scholarships$q$,$q$In person$q$,$q$Funded$q$,$q$International applicants to APU$q$,$q$All international students may apply, and you must apply as an international applicant. You need a Student status of residence while studying at APU. You send two 200-word essays and a letter of recommendation.$q$,null,false,true,$q$https://admissions.apu.ac.jp/costs_scholarships/before_enrollment/?&lang=en$q$,array[$q$japan$q$]::text[],$q$2026-10-17$q$::date),
($q$tohoku-fgl-undergraduate-program$q$,$q$Tohoku University Future Global Leadership (FGL) Undergraduate Program$q$,$q$Tohoku University$q$,$q$FGL has three English-taught four-year degrees: Advanced Molecular Chemistry, International Mechanical and Aerospace Engineering, and Applied Marine Biology. Admission is in October and the application period is January; the page is the October 2025 guide and gives no closing date. Tuition is 535,800 JPY a year; the MEXT scholarship is recommended for only 8 applicants and the President Fellowship can waive tuition.$q$,$q$Universities$q$,$q$In person$q$,$q$Not stated$q$,$q$Applicants with 12 years of non-Japanese education$q$,$q$Applicants need 12 years of education under a non-Japanese system (11 years are assessed case by case), exam results in the required subjects (A-Levels, IB, ACT, AP or EJU), and TOEFL iBT 79+ or IELTS 6.0+.$q$,null,false,true,$q$https://www.insc.tohoku.ac.jp/english/?p=72467$q$,array[$q$japan$q$]::text[],$q$2026-10-17$q$::date)
