-- Adds the Europe, North America, Turkey/Gulf/Asia opportunities and country tags. Safe to run again.
on conflict (id) do update set title=excluded.title, org=excluded.org, descr=excluded.descr, category=excluded.category, mode=excluded.mode, cost=excluded.cost, grade=excluded.grade, eligibility=excluded.eligibility, deadline=excluded.deadline, url=excluded.url, tags=excluded.tags, last_verified=excluded.last_verified, published=true;
update public.opportunities set tags = array(select distinct unnest(tags || array['uk'])) where id='chevening';
update public.opportunities set tags = array(select distinct unnest(tags || array['uk'])) where id='gates';
