update public.opportunities set tags = array(select distinct unnest(tags || array['usa'])) where id='fulbright';
update public.opportunities set tags = array(select distinct unnest(tags || array['usa'])) where id='usembassy-eg';
update public.opportunities set tags = array(select distinct unnest(tags || array['uae'])) where id='nyuad';
update public.opportunities set tags = array(select distinct unnest(tags || array['uae'])) where id='mbzuai';
